L = "abcdefghijklmnopqrstuvwxyz"
ops = ["StreamReceiver", "set_delay"]; xs = [[128], [60]]
ev = []
T = 0
for g in range(800):
    n = r.randint(20, 150)
    cut = r.randint(n // 2, n + 10)
    for s in range(min(n, cut)):
        if r.random() < 0.03:
            continue
        ev.append((T + 20 * s + r.randint(0, 80), 0, s, g))
        if r.random() < 0.03:
            ev.append((T + 20 * s + r.randint(0, 300), 0, s, g))
    T += 20 * cut
    ev.append((T + r.randint(0, 50), 1, 0, g + 1))
for p in range(0, T + 400, 37):
    ev.append((p, 2, 0, 0))
ev.sort()
for at, kind, s, g in ev:
    if kind == 0:
        ops.append("receive"); xs.append([s, L[(s + g) % 26], at, g])
    elif kind == 1:
        ops.append("interrupt"); xs.append([g, at])
    else:
        ops.append("play"); xs.append([at])
args = {"ops": ops, "args": xs}

